```typescript
import React, { useState, useEffect } from 'react';
import { Process, Worknode, ProcessFormInputs, WorknodeFormInputs, ProcessStatus } from './types';
import ProcessList from './components/ProcessList';
import ProcessForm from './components/ProcessForm';
import WorknodeList from './components/WorknodeList';
import WorknodeForm from './components/WorknodeForm';
import ProcessDiagram from './components/ProcessDiagram';

const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
const getCurrentDateTime = () => new Date().toISOString();

const App: React.FC = () => {
    const [processes, setProcesses] = useState<Process[]>([]);
    const [worknodes, setWorknodes] = useState<Worknode[]>([]);
    const [selectedProcessId, setSelectedProcessId] = useState<string | null>(null);
    const [showProcessForm, setShowProcessForm] = useState(false);
    const [editingProcess, setEditingProcess] = useState<Process | null>(null);
    const [showWorknodeForm, setShowWorknodeForm] = useState(false);
    const [editingWorknode, setEditingWorknode] = useState<Worknode | null>(null);

    // 컴포넌트 마운트 시 localStorage에서 데이터 로드
    useEffect(() => {
        if (typeof window !== 'undefined') { // 브라우저 환경에서만 실행
            const savedProcesses = localStorage.getItem('processes');
            const savedWorknodes = localStorage.getItem('worknodes');

            const initialProcesses: Process[] = savedProcesses
                ? JSON.parse(savedProcesses)
                : [
                    { id: generateId(), name: '제품 생산 프로세스', description: '제품 생산의 전반적인 흐름', created_at: getCurrentDateTime(), updated_at: getCurrentDateTime() },
                    { id: generateId(), name: '품질 관리 프로세스', description: '생산된 제품의 품질 검사 및 관리', created_at: getCurrentDateTime(), updated_at: getCurrentDateTime() },
                ];
            const initialWorknodes: Worknode[] = savedWorknodes ? JSON.parse(savedWorknodes) : [];

            setProcesses(initialProcesses);
            setWorknodes(initialWorknodes);

            if (initialProcesses.length > 0) {
                setSelectedProcessId(initialProcesses[0].id);
            }
        }
    }, []); // 빈 의존성 배열은 컴포넌트가 처음 마운트될 때 한 번만 실행됨을 의미

    // processes 상태 변경 시 localStorage에 저장
    useEffect(() => {
        if (typeof window !== 'undefined') {
            localStorage.setItem('processes', JSON.stringify(processes));
        }
    }, [processes]);

    // worknodes 상태 변경 시 localStorage에 저장
    useEffect(() => {
        if (typeof window !== 'undefined') {
            localStorage.setItem('worknodes', JSON.stringify(worknodes));
        }
    }, [worknodes]);

    const handleAddProcess = (data: ProcessFormInputs) => {
        const newProcess: Process = {
            id: generateId(),
            name: data.name,
            description: data.description,
            created_at: getCurrentDateTime(),
            updated_at: getCurrentDateTime(),
        };
        setProcesses((prev) => [...prev, newProcess]);
        setShowProcessForm(false);
        if (!selectedProcessId) {
            setSelectedProcessId(newProcess.id);
        }
    };

    const handleUpdateProcess = (data: ProcessFormInputs) => {
        if (!editingProcess) return;
        setProcesses((prev) =>
            prev.map((p) =>
                p.id === editingProcess.id
                    ? { ...p, name: data.name, description: data.description, updated_at: getCurrentDateTime() }
                    : p
            )
        );
        setShowProcessForm(false);
        setEditingProcess(null);
    };

    const handleDeleteProcess = (processId: string) => {
        setProcesses((prev) => prev.filter((p) => p.id !== processId));
        setWorknodes((prev) => prev.filter((wn) => wn.process_id !== processId));
        if (selectedProcessId === processId) {
            setSelectedProcessId(processes.length > 1 ? processes.filter(p => p.id !== processId)[0]?.id || null : null);
        }
    };

    const handleAddWorknode = (data: WorknodeFormInputs) => {
        if (!selectedProcessId) return;
        const newWorknode: Worknode = {
            id: generateId(),
            process_id: selectedProcessId,
            name: data.name,
            department: data.department,
            assignee: data.assignee,
            input_data: data.input_data,
            output_data: data.output_data,
            status: data.status,
            sequence: data.sequence,
            created_at: getCurrentDateTime(),
        };
        setWorknodes((prev) => [...prev, newWorknode]);
        setShowWorknodeForm(false);
    };

    const handleUpdateWorknode = (data: WorknodeFormInputs) => {
        if (!editingWorknode) return;
        setWorknodes((prev) =>
            prev.map((wn) =>
                wn.id === editingWorknode.id
                    ? {
                        ...wn,
                        name: data.name,
                        department: data.department,
                        assignee: data.assignee,
                        input_data: data.input_data,
                        output_data: data.output_data,
                        status: data.status,
                        sequence: data.sequence,
                    }
                    : wn
            )
        );
        setShowWorknodeForm(false);
        setEditingWorknode(null);
    };

    const handleDeleteWorknode = (worknodeId: string) => {
        setWorknodes((prev) => prev.filter((wn) => wn.id !== worknodeId));
    };

    const selectedProcess = processes.find((p) => p.id === selectedProcessId);
    const currentWorknodes = worknodes.filter((wn) => wn.process_id === selectedProcessId);

    return (
        <div className="min-h-screen bg-gray-100 p-4 sm:p-6 lg:p-8 flex flex-col">
            <h1 className="text-3xl font-bold text-gray-800 mb-6 text-center">제조업 업무 프로세스 관리</h1>

            {/* 프로세스 목록 및 관리 */}
            <div className="bg-white shadow-lg rounded-lg p-6 mb-8">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-2xl font-semibold text-gray-700">프로세스 목록</h2>
                    <button
                        onClick={() => { setShowProcessForm(true); setEditingProcess(null); }}
                        className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg transition duration-300 ease-in-out"
                    >
                        새 프로세스 추가
                    </button>
                </div>
                <ProcessList
                    processes={processes}
                    selectedProcessId={selectedProcessId}
                    onSelectProcess={setSelectedProcessId}
                    onEditProcess={(process) => { setEditingProcess(process); setShowProcessForm(true); }}
                    onDeleteProcess={handleDeleteProcess}
                />
            </div>

            {/* 프로세스 추가/수정 폼 */}
            {showProcessForm && (
                <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex justify-center items-center z-50">
                    <div className="bg-white p-8 rounded-lg shadow-xl w-full max-w-md">
                        <h3 className="text-xl font-bold mb-4">{editingProcess ? '프로세스 수정' : '새 프로세스 추가'}</h3>
                        <ProcessForm
                            process={editingProcess}
                            onSubmit={editingProcess ? handleUpdateProcess : handleAddProcess}
                            onCancel={() => { setShowProcessForm(false); setEditingProcess(null); }}
                        />
                    </div>
                </div>
            )}

            {/* 선택된 프로세스 상세 및 워크노드 관리 */}
            {selectedProcess && (
                <div className="bg-white shadow-lg rounded-lg p-6 mb-8 flex-grow flex flex-col">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-2xl font-semibold text-gray-700">
                            {selectedProcess.name} 워크플로우
                        </h2>
                        <button
                            onClick={() => { setShowWorknodeForm(true); setEditingWorknode(null); }}
                            className="bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-4 rounded-lg transition duration-300 ease-in-out"
                        >
                            새 워크노드 추가
                        </button>
                    </div>

                    {/* 워크노드 다이어그램 */}
                    <div className="mb-6 border border-gray-200 rounded-lg p-4 overflow-x-auto">
                        <h3 className="text-xl font-semibold text-gray-700 mb-3">프로세스 흐름도</h3>
                        {currentWorknodes.length > 0 ? (
                            <ProcessDiagram worknodes={currentWorknodes} />
                        ) : (
                            <p className="text-gray-500 text-center py-8">워크노드가 없습니다. 추가해주세요.</p>
                        )}
                    </div>

                    {/* 워크노드 목록 */}
                    <div className="flex-grow">
                        <h3 className="text-xl font-semibold text-gray-700 mb-3">단위 업무 목록</h3>
                        {currentWorknodes.length > 0 ? (
                            <WorknodeList
                                worknodes={currentWorknodes}
                                onEditWorknode={(worknode) => { setEditingWorknode(worknode); setShowWorknodeForm(true); }}
                                onDeleteWorknode={handleDeleteWorknode}
                            />
                        ) : (
                            <p className="text-gray-500 text-center py-8">워크노드가 없습니다. 추가해주세요.</p>
                        )}
                    </div>
                </div>
            )}

            {/* 워크노드 추가/수정 폼 */}
            {showWorknodeForm && (
                <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex justify-center items-center z-50">
                    <div className="bg-white p-8 rounded-lg shadow-xl w-full max-w-md">
                        <h3 className="text-xl font-bold mb-4">{editingWorknode ? '워크노드 수정' : '새 워크노드 추가'}</h3>
                        <WorknodeForm
                            worknode={editingWorknode}
                            onSubmit={editingWorknode ? handleUpdateWorknode : handleAddWorknode}
                            onCancel={() => { setShowWorknodeForm(false); setEditingWorknode(null); }}
                        />
                    </div>
                </div>
            )}
        </div>
    );
};

export default App;
```

