  switch (status) {
    case 'PENDING':
      return '#cbd5e1'; // slate-300
    case 'IN_PROGRESS':
      return '#a5b4fc'; // indigo-300
    case 'COMPLETED':
      return '#6ee7b7'; // emerald-300
    default:
      return '#cbd5e1';
  }
};

const getStatusTextColor = (status: ProcessStatus) => {
  switch (status) {
    case 'PENDING':
      return '#475569'; // slate-700
    case 'IN_PROGRESS':
      return '#4f46e5'; // indigo-700
    case 'COMPLETED':
      return '#059669'; // emerald-700
    default:
      return '#475569';
  }
};

const ProcessDiagram: React.FC<ProcessDiagramProps> = ({ worknodes }) => {
  if (worknodes.length === 0) {
    return (
      <div className="card p-6 space-y-4">
        <h2 className="text-lg font-semibold text-slate-800">프로세스 다이어그램</h2>
        <div className="text-center text-slate-400 py-12">
          <p className="text-4xl mb-2">📊</p>
          <p>다이어그램을 표시할 워크노드가 없습니다.</p>
        </div>
      </div>
    );
  }

  const sortedWorknodes = [...worknodes].sort((a, b) => a.sequence - b.sequence);

  // Calculate node positions
  const nodePositions = new Map<string, { x: number; y: number }>();
  let currentX = HORIZONTAL_GAP / 2;
  let currentY = VERTICAL_GAP / 2;

  sortedWorknodes.forEach((node, index) => {
    nodePositions.set(node.id, { x: currentX, y: currentY });
    currentX += NODE_WIDTH + HORIZONTAL_GAP;
  });

  const svgWidth = currentX - HORIZONTAL_GAP / 2;
  const svgHeight = NODE_HEIGHT + VERTICAL_GAP;

  return (
    <div className="card p-6 space-y-4 overflow-x-auto">
      <h2 className="text-lg font-semibold text-slate-800">프로세스 다이어그램</h2>
      <svg width={svgWidth} height={svgHeight} className="border border-slate-200 rounded-lg bg-white">
        <defs>
          <marker
            id="arrowhead"
            markerWidth="10"
            markerHeight="7"
            refX="0"
            refY="3.5"
            orient="auto"
          >
            <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" /> {/* slate-400 */}
          </marker>
        </defs>

        {/* Draw arrows */}
        {sortedWorknodes.map((node, index) => {
          if (index < sortedWorknodes.length - 1) {
            const startNodePos = nodePositions.get(node.id);
            const endNodePos = nodePositions.get(sortedWorknodes[index + 1].id);

            if (startNodePos && endNodePos) {
              const startX = startNodePos.x + NODE_WIDTH;
              const startY = startNodePos.y + NODE_HEIGHT / 2;
              const endX = endNodePos.x;
              const endY = endNodePos.y + NODE_HEIGHT / 2;

              return (
                <line
                  key={`arrow-${node.id}-${sortedWorknodes[index + 1].id}`}
                  x1={startX}
                  y1={startY}
                  x2={endX}
                  y2={endY}
                  stroke="#94a3b8" // slate-400
                  strokeWidth="2"
                  markerEnd="url(#arrowhead)"
                />
              );
            }
          }
          return null;
        })}

        {/* Draw nodes */}
        {sortedWorknodes.map((node) => {
          const pos = nodePositions.get(node.id);
          if (!pos) return null;

          return (
            <g key={node.id} transform={`translate(${pos.x}, ${pos.y})`}>
              <rect
                x="0"
                y="0"
                width={NODE_WIDTH}
                height={NODE_HEIGHT}
                rx="8"
                ry="8"
                fill={getStatusColor(node.status)}
                stroke="#e2e8f0" // slate-200
                strokeWidth="1"
              />
              <text
                x={NODE_WIDTH / 2}
                y="25"
                textAnchor="middle"
                className="text-sm font-semibold"
                fill={getStatusTextColor(node.status)}
              >
                {node.sequence}. {node.name}
              </text>
              <text
                x={NODE_WIDTH / 2}
                y="45"
                textAnchor="middle"
                className="text-xs"
                fill="#475569" // slate-700
              >
                담당: {node.assignee} ({node.department})
              </text>
              <text
                x={NODE_WIDTH / 2}
                y="65"
                textAnchor="middle"
                className="text-xs"
                fill="#475569"
              >
                Input: {node.input_data.substring(0, 15)}{node.input_data.length > 15 ? '...' : ''}
              </text>
              <text
                x={NODE_WIDTH / 2}
                y="80"
                textAnchor="middle"
                className="text-xs"
                fill="#475569"
              >
                Output: {node.output_data.substring(0, 15)}{node.output_data.length > 15 ? '...' : ''}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
};

