<CODE>
import { Category, Unit, CategoryConfig } from '../types';

const categoryConfigs: Record<Category, CategoryConfig> = {
  length: {
    units: [
      { id: 'cm', name: '센티미터' },
      { id: 'inch', name: '인치' },
    ],
    conversions: {
      cm_to_inch: (cm) => cm / 2.54,
      inch_to_cm: (inch) => inch * 2.54,
    },
  },
  weight: {
    units: [
      { id: 'kg', name: '킬로그램' },
      { id: 'lb', name: '파운드' },
    ],
    conversions: {
      kg_to_lb: (kg) => kg * 2.20462,
      lb_to_kg: (lb) => lb / 2.20462,
    },
  },
  temperature: {
    units: [
      { id: 'celsius', name: '섭씨' },
      { id: 'fahrenheit', name: '화씨' },
    ],
    conversions: {
      celsius_to_fahrenheit: (c) => (c * 9) / 5 + 32,
      fahrenheit_to_celsius: (f) => ((f - 32) * 5) / 9,
    },
  },
};

export const getAvailableUnits = (category: Category): Unit[] => {
  return categoryConfigs[category]?.units || [];
};

export const convertValue = (value: number, fromUnit: string, toUnit: string): number | null => {
  if (isNaN(value)) {
    return null;
  }

  for (const category in categoryConfigs) {
    const config = categoryConfigs[category as Category];
    const conversionKey = `${fromUnit}_to_${toUnit}`;
    const reverseConversionKey = `${toUnit}_to_${fromUnit}`;

    if (config.conversions[conversionKey]) {
      const result = config.conversions[conversionKey](value);
      return parseFloat(result.toFixed(3));
    }
  }
  return null;
};
</CODE>
</INSTRUCTION>
<INSTRUCTION>
<FILE_PATH>src/App.tsx</FILE_PATH>
<PURPOSE>변환 로직을 호출하고 UI에 결과를 반영</PURPOSE>
<CODE>
import React, { useState, useEffect } from 'react';
import { Category } from './types';
import { getAvailableUnits, convertValue } from './utils/conversionLogic';
import { getConversionHistory, addConversionHistory } from './utils/localStorage';
import CategoryTabs from './components/CategoryTabs';
import ConversionForm from './components/ConversionForm';
import HistoryList from './components/HistoryList';

function App() {
  const [currentCategory, setCurrentCategory] = useState<Category>('length');
  const [inputValue, setInputValue] = useState<string>('');
  const [inputUnit, setInputUnit] = useState<string>('');
  const [outputValue, setOutputValue] = useState<string>('');
  const [outputUnit, setOutputUnit] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [history, setHistory] = useState(getConversionHistory());

  const availableUnits = getAvailableUnits(currentCategory);

  useEffect(() => {
    // 카테고리 변경 시 단위 초기화
    if (availableUnits.length > 0) {
      setInputUnit(availableUnits[0].id);
      setOutputUnit(availableUnits.length > 1 ? availableUnits[1].id : availableUnits[0].id);
    } else {
      setInputUnit('');
      setOutputUnit('');
    }
    setInputValue('');
    setOutputValue('');
    setError('');
  }, [currentCategory, availableUnits]);

  const handleConvert = () => {
    setError('');
    if (inputValue === '' || isNaN(Number(inputValue))) {
      setError('유효한 숫자를 입력해주세요.');
      setOutputValue('');
      return;
    }
    if (!inputUnit || !outputUnit) {
      setError('단위를 선택해주세요.');
      setOutputValue('');
      return;
    }

    const numValue = Number(inputValue);
    const converted = convertValue(numValue, inputUnit, outputUnit);

    if (converted !== null) {
      setOutputValue(converted.toString());
      const newEntry = {
        category: currentCategory,
        inputValue: numValue,
        inputUnit,
        outputValue: converted,
        outputUnit,
        timestamp: Date.now(),
      };
      const updatedHistory = addConversionHistory(newEntry);
      setHistory(updatedHistory);
    } else {
      setError('변환할 수 없는 단위 조합입니다.');
      setOutputValue('');
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-lg shadow-xl w-full max-w-md">
        <h1 className="text-3xl font-bold text-center mb-6 text-indigo-700">단위 변환기</h1>

        <CategoryTabs currentCategory={currentCategory} onSelectCategory={setCurrentCategory} />

        <ConversionForm
          inputValue={inputValue}
          setInputValue={setInputValue}
          inputUnit={inputUnit}
          setInputUnit={setInputUnit}
          outputValue={outputValue}
          outputUnit={outputUnit}
          setOutputUnit={setOutputUnit}
          availableUnits={availableUnits}
          onConvert={handleConvert}
          error={error}
        />

        <HistoryList history={history} />
      </div>
    </div>
  );
}

export default App;
</CODE>
