export interface Unit {
  key: string;
  name: string;
}

export interface CategoryConfig {
  units: { [key: string]: string };
  conversions: { [key: string]: (val: number) => number };
  defaultInput: string;
  defaultOutput: string;
}

export interface ConversionHistoryEntry {
  id: string;
  category: Category;
  inputValue: number;
  inputUnit: string;
  outputValue: number;
  outputUnit: string;
  timestamp: number;
