"}, {"file_path": "src/utils/conversionLogic.ts", "code": "import { Category, CategoryConfig, Unit } from '../types';

export const categoriesConfig: { [key in Category]: CategoryConfig } = {
  length: {
    units: { cm: '센티미터', inch: '인치' },
    conversions: {
      'cm_to_inch': (val) => val / 2.54,
      'inch_to_cm': (val) => val * 2.54,
    },
    defaultInput: 'cm',
    defaultOutput: 'inch',
  },
  weight: {
    units: { kg: '킬로그램', lb: '파운드' },
    conversions: {
      'kg_to_lb': (val) => val * 2.20462,
      'lb_to_kg': (val) => val / 2.20462,
    },
    defaultInput: 'kg',
    defaultOutput: 'lb',
  },
  temperature: {
    units: { celsius: '섭씨', fahrenheit: '화씨' },
    conversions: {
      'celsius_to_fahrenheit': (val) => (val * 9 / 5) + 32,
      'fahrenheit_to_celsius': (val) => (val - 32) * 5 / 9,
    },
    defaultInput: 'celsius',
    defaultOutput: 'fahrenheit',
  },
};

export const getAvailableUnits = (category: Category): Unit[] => {
  const config = categoriesConfig[category];
  if (config) {
    return Object.entries(config.units).map(([key, name]) => ({
      key,
      name
    }));
  }
  return [];
};

export function convertValue(
  category: Category,
  value: number,
  inputUnit: string,
  outputUnit: string
): number | null {
  const config = categoriesConfig[category];
  if (!config) return null;

  if (inputUnit === outputUnit) {
    return parseFloat(value.toFixed(3)); // 같은 단위일 경우 소수점 처리만
  }

  const conversionKey = `${inputUnit}_to_${outputUnit}`;
  const conversionFunction = config.conversions[conversionKey];

  if (conversionFunction) {
    const result = conversionFunction(value);
    return parseFloat(result.toFixed(3));
  }

  // 양방향 변환을 위해 역방향 키도 확인
  const reverseConversionKey = `${outputUnit}_to_${inputUnit}`;
  const reverseConversionFunction = config.conversions[reverseConversionKey];

  if (reverseConversionFunction) {
    // 역변환 함수가 존재하면, 역변환 후 다시 역변환하여 원래 방향의 변환을 시도
    // 이 부분은 현재 로직에서는 필요 없지만, 일반적인 양방향 변환 로직을 고려할 때 포함될 수 있음.
    // 현재는 `fromUnit_to_toUnit` 형태의 키만 사용하므로, 이 블록은 실행되지 않음.
    // 하지만, `convertValue` 함수의 인터페이스가 `fromUnit`과 `toUnit`을 명시적으로 받으므로,
    // `conversionKey`를 통해 직접 변환을 시도하는 것이 올바른 접근 방식입니다.
    // 따라서 이 부분은 제거하거나, `conversionKey`를 찾지 못했을 때의 대체 로직으로만 사용해야 합니다.
    // 현재 구현은 `conversionKey`를 직접 찾으므로, 이 부분은 불필요합니다.
  }

  return null;
}
"}, {"file_path": "src/utils/localStorage.ts", "code": "import { ConversionHistoryEntry } from '../types';

const HISTORY_KEY = 'conversionHistory';
const MAX_HISTORY_ITEMS = 5;

export function getHistory(): ConversionHistoryEntry[] {
  try {
    const historyString = localStorage.getItem(HISTORY_KEY);
    if (historyString) {
      const parsedHistory = JSON.parse(historyString);
      if (Array.isArray(parsedHistory) && parsedHistory.every(item =>
        typeof item.id === 'string' &&
        typeof item.category === 'string' &&
        typeof item.inputValue === 'number' &&
        typeof item.inputUnit === 'string' &&
        typeof item.outputValue === 'number' &&
        typeof item.outputUnit === 'string' &&
        typeof item.timestamp === 'number' &&
        typeof item.displayString === 'string'
      )) {
        return parsedHistory;
      }
    }
  } catch (e) {
    console.error('Failed to parse conversion history from localStorage', e);
  }
  return [];
}

export function addHistoryEntry(entry: ConversionHistoryEntry): ConversionHistoryEntry[] {
  const currentHistory = getHistory();
  const newHistory = [entry, ...currentHistory];
  if (newHistory.length > MAX_HISTORY_ITEMS) {
    newHistory.pop();
  }
  localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
  return newHistory;
}

export function removeHistoryEntry(idToRemove: string): ConversionHistoryEntry[] {
  const currentHistory = getHistory();
  const newHistory = currentHistory.filter(entry => entry.id !== idToRemove);
  localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
  return newHistory;
}
