"}, {"file_path": "src/utils/conversionUtils.ts", "code": "import { CategoriesConfig, Category } from '../types';

export const categoriesConfig: CategoriesConfig = {
  length: {
    units: ['cm', 'inch'],
    convert: (value, fromUnit, toUnit) => {
      if (fromUnit === 'cm' && toUnit === 'inch') return value / 2.54;
      if (fromUnit === 'inch' && toUnit === 'cm') return value * 2.54;
      return value; // Same unit or unsupported combination
    },
  },
  weight: {
    units: ['kg', 'lb'],
    convert: (value, fromUnit, toUnit) => {
      if (fromUnit === 'kg' && toUnit === 'lb') return value * 2.20462;
      if (fromUnit === 'lb' && toUnit === 'kg') return value / 2.20462;
      return value;
    },
  },
  temperature: {
    units: ['섭씨', '화씨'],
    convert: (value, fromUnit, toUnit) => {
      if (fromUnit === '섭씨' && toUnit === '화씨') return (value * 9) / 5 + 32;
      if (fromUnit === '화씨' && toUnit === '섭씨') return (value - 32) * 5 / 9;
      return value;
    },
  },
};

export const HISTORY_MAX_ITEMS = 5;
export const LOCAL_STORAGE_KEY = 'conversionHistories';

export const getHistory = () => {
  const historyJson = localStorage.getItem(LOCAL_STORAGE_KEY);
  return historyJson ? JSON.parse(historyJson) : [];
};

export const saveHistory = (history: any[]) => {
  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(history));
};

export const validateInput = (value: string): boolean => {
  const num = parseFloat(value);
  return !isNaN(num) && num >= 0; // 양의 숫자만 허용
};

export const performConversionLogic = (
  inputValue: number,
  inputUnit: string,
  outputUnit: string,
  category: Category
): number => {
  const config = categoriesConfig[category];
  if (!config) {
    console.error(`알 수 없는 카테고리: ${category}`);
    return NaN;
  }

  let convertedValue = config.convert(inputValue, inputUnit, outputUnit);

  return convertedValue;
};
